import json

async def execute(self, inputs):
    action      = str(inputs.get('action') or self.parameters.get('action', 'list') or 'list')
    standard_id = str(inputs.get('standard_id') or self.parameters.get('standard_id', '') or '')
    category    = str(inputs.get('category') or self.parameters.get('category', '') or '')
    value_json  = str(inputs.get('value_json') or self.parameters.get('value_json', '') or '')
    description = str(inputs.get('description') or self.parameters.get('description', '') or '')

    try:
        from src.runtime.studio.studio_standards import get_studio_standards
        ss = get_studio_standards()
        ok = True
        is_approved = False

        if action == 'get' and standard_id:
            result = ss.get_standard(standard_id)
            if result is None:
                result = {'error': f'Standard not found: {standard_id}'}
                ok = False
        elif action == 'check' and category:
            value = value_json.strip('"') if value_json else ''
            is_approved = ss.is_approved(category, value)
            result = {'category': category, 'value': value, 'approved': is_approved}
        elif action == 'update' and standard_id and value_json:
            try:
                val = json.loads(value_json)
            except Exception:
                val = value_json
            ok = ss.update_standard(standard_id, val, description)
            result = {'updated': ok, 'standard_id': standard_id}
        elif action == 'register' and standard_id and category:
            try:
                val = json.loads(value_json) if value_json else ''
            except Exception:
                val = value_json
            ss.register_standard(standard_id, category, val, description)
            result = {'registered': True, 'standard_id': standard_id}
        else:
            standards = ss.list_standards(category=category or None)
            result = {'standards': standards}

        stats = ss.stats()
        self.log_info(f'[StudioStandards] Action={action!r} ok={ok}')
        return {
            'standards_json': json.dumps(result, sort_keys=True),
            'standard_count': stats.get('total_standards', 0),
            'is_approved':    is_approved,
            'ok':             ok,
            'exec_out':       True,
        }
    except Exception as e:
        self.log_error(f'[StudioStandards] {e}')
        return {
            'standards_json': json.dumps({'error': str(e)}),
            'standard_count': 0, 'is_approved': False,
            'ok': False, 'exec_out': True,
        }

def register_node():
    from src.nodes.base import BaseNode
    class Hou_Mcp_Studio_Standards(BaseNode):
        name = 'hou_mcp_studio_standards'
        async def execute(self, inputs):
            return await execute(self, inputs)
    return Hou_Mcp_Studio_Standards
